const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-122.555169, 40.190004]);
  const date = '2020-08-25';

  // 2. Data Acquisition - MERRA-2 for black carbon
  const collection = ee.ImageCollection('NASA/GSFC/MERRA/aer/2')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(point);

  const collectionSize = collection.size().getInfo();
  console.log(`MERRA-2 Images on ${date}: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get black carbon data
  const image = collection.first();

  // Black carbon mass mixing ratio (kg/kg) - using total black carbon
  const bcMixingRatio = image.select('BCSMASS');

  // Convert to concentration (mg/m^3) using air density
  // Air density from MERRA-2 (kg/m^3)
  const airDensity = image.select('RHOA');
  const bcConcentration = bcMixingRatio.multiply(airDensity).multiply(1e6); // Convert kg/m^3 to mg/m^3

  // 4. Extract value at point
  const result = bcConcentration.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: 1000,
    maxPixels: 1e9
  });

  const bcValue = result.get('BCSMASS').getInfo();
  const pixelCount = bcConcentration.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point,
    scale: 1000,
    maxPixels: 1e9
  }).get('BCSMASS').getInfo();

  console.log(`Black Carbon: ${bcValue ? bcValue.toFixed(3) : 'null'} mg/m³`);
  console.log(`Valid Pixels: ${pixelCount}`);

  // 5. Validation & Final Answer
  if (bcValue === null || bcValue === undefined || !isFinite(bcValue)) {
    console.log("<answer>C3</answer>");
  } else if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
  } else if (bcValue > 12) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
